package org.codex.nfsugpreview;
/** Complete original window-filtered OBJ candidates for native BG composition. */
final class NativeHudCandidates {
 static final class Row {private final int[] colors,tags;private final byte[] visible,backdrop;Row(int[] c,int[] t,byte[] v,byte[] b){colors=c;tags=t;visible=v;backdrop=b;}int[] colors(){return colors.clone();}int[] tags(){return tags.clone();}byte[] visible(){return visible.clone();}byte[] backdrop(){return backdrop.clone();}}
 static Row prepare(byte[] vram,byte[] palette,byte[] oam,int display,int row,int[] window,int blend,int brightness){if(vram==null||vram.length<98304||palette==null||palette.length<1024||oam==null||oam.length<1024||row<0||row>=160||(display&0x8080)!=0)throw new IllegalArgumentException("Unsupported HUD candidate row");NativeHudRules.Windows masks=NativeHudRules.windows(display,row,window);byte[] visible=masks.visible(),backdrop=masks.backdrop();int needed=0;for(byte value:visible)if((display&0x1000)!=0&&(value&16)!=0)needed|=1<<((value&32)!=0?1:0);int[][] colors=new int[2][],tags=new int[2][];for(int i=0;i<2;i++)if((needed&(1<<i))!=0){NativeObjScanline.Row prepared=NativeObjScanline.prepared(vram,palette,oam,display&~0xe000,row,i!=0?blend:blend&0x3f00,brightness);colors[i]=prepared.colors();tags[i]=prepared.tags();}int[] result=new int[240],metadata=new int[240];for(int x=0;x<240;x++)if((display&0x1000)!=0&&(visible[x]&16)!=0){int i=(visible[x]&32)!=0?1:0;result[x]=colors[i][x];metadata[x]=tags[i][x];}else metadata[x]=-1;return new Row(result,metadata,visible,backdrop);}
}
